<script setup lang="ts">
import { computed,ref,watch,nextTick } from 'vue'
import { colorLabels,isHex,contrast,effectiveColors,withColors,clearColors,appearanceAttrs,resolvedStyle,type ColorKey,type ColorMode,type Palette } from './colors'
import type { Appearance } from './types'
const props=defineProps<{appearance:Appearance;previewMode:'follow'|ColorMode;resetKey:number}>()
const emit=defineEmits<{(e:'update',value:Appearance):void;(e:'preview',value:'follow'|ColorMode):void;(e:'invalid',value:boolean):void}>()
const probe=ref<HTMLElement|null>(null)
const mode=ref<ColorMode>('light'),raw=ref<Palette>({}),defaults=ref<Record<string,string>>({})
const palette=computed(()=>effectiveColors(props.appearance,mode.value))
// Read the reader theme tokens from an inert probe, without mutating the preview.
// Keep warnings informative: translucent backgrounds are conservatively checked
// against the opaque theme surface and page; screenshot tests check real rendering.
async function readDefaults(){await nextTick();const root=probe.value;if(!root)return;const s=getComputedStyle(root),get=(key:string)=>s.getPropertyValue(key).trim();defaults.value={page_background:get('--bg'),card_background:get('--surface'),body_text:get('--ink'),heading_text:get('--ink'),muted_text:get('--muted'),nav_background:get('--surface'),nav_text:get('--ink'),link:get('--accent'),primary_background:get('--accent'),primary_text:mode.value==='dark'?get('--bg'):'#ffffff',secondary_background:get('--surface'),secondary_text:get('--ink'),tag_background:get('--bg'),tag_text:get('--ink'),border:get('--line'),accent:get('--accent')};for(const [k,v] of Object.entries(defaults.value))if(/^#[\da-f]{3}$/i.test(v))defaults.value[k]='#'+v.slice(1).split('').map(c=>c+c).join('')}
watch(()=>[props.appearance.theme,props.appearance.style,props.appearance.palette,props.resetKey],()=>{raw.value={};void readDefaults()},{immediate:true})
watch(()=>props.previewMode,()=>void readDefaults())
watch(raw,()=>emit('invalid',Object.values(raw.value).some(v=>!isHex(v))),{deep:true})
function changeMode(value:ColorMode){mode.value=value;raw.value={};emit('preview',value);void readDefaults()}
function update(key:ColorKey,value?:string){const p={...palette.value};if(value===undefined)delete p[key];else p[key]=value;emit('update',withColors(props.appearance,mode.value,p))}
function input(key:ColorKey,value:string){raw.value[key]=value;if(isHex(value))update(key,value)}
function clearTheme(){raw.value={};emit('update',clearColors(props.appearance))}
const effective=(key:ColorKey):string=>palette.value[key]||(key==='nav_background'&&resolvedStyle(props.appearance)!=='glass'?palette.value.page_background:undefined)||defaults.value[key]||'#ffffff'
const warnings=computed(()=>{const pairs:[ColorKey,ColorKey][]=[['body_text','page_background'],['body_text','card_background'],['heading_text','page_background'],['heading_text','card_background'],['muted_text','page_background'],['muted_text','card_background'],['link','page_background'],['link','card_background'],['nav_text','nav_background'],['primary_text','page_background'],['primary_text','primary_background'],['secondary_text','secondary_background'],['tag_text','tag_background']];return pairs.filter(([a,b])=>palette.value[a]||palette.value[b]).map(([a,b])=>({label:colorLabels[a]+' / '+colorLabels[b],ratio:contrast(effective(a),effective(b))})).filter(x=>x.ratio<4.5)})
</script>
<template><section class="color-editor" aria-label="独立元素颜色"><div ref="probe" class="color-default-probe" v-bind="appearanceAttrs(appearance)" :data-mode="mode" hidden aria-hidden="true"></div><h3>独立元素颜色</h3><p>影响私人 Blog 和写作工作台，后台管理保持中性配色。每项可跟随主题，也可输入六位 HEX。切换风格或配色保留其他组合设置。</p><div class="editor-meta"><label>编辑颜色模式<select :value="mode" aria-label="编辑颜色模式" @change="changeMode(($event.target as HTMLSelectElement).value as ColorMode)"><option value="light">浅色颜色</option><option value="dark">深色颜色</option></select></label><label>预览明暗模式<select :value="previewMode" aria-label="预览明暗模式" @change="emit('preview',($event.target as HTMLSelectElement).value as 'follow'|ColorMode)"><option value="follow">跟随正式配色设置</option><option value="light">仅预览浅色</option><option value="dark">仅预览深色</option></select></label></div><p class="muted">编辑浅色或深色会同步切换预览；不会改变正式的配色模式（包括跟随系统）。低对比度警告不阻止保存。</p><div class="color-grid"><div v-for="(label,key) in colorLabels" :key="key" class="color-row"><strong>{{label}}</strong><label class="checks"><input type="checkbox" :aria-label="label+'跟随主题'" :checked="!palette[key]" @change="delete raw[key];update(key,palette[key]?undefined:effective(key))" />跟随当前主题</label><div class="color-inputs"><input type="color" :aria-label="label+'颜色选择器'" :disabled="!palette[key]" :value="palette[key]||effective(key)" @input="delete raw[key];update(key,($event.target as HTMLInputElement).value)" /><input :aria-label="label+' HEX'" :disabled="!palette[key]" :value="raw[key]??palette[key]??''" placeholder="#RRGGBB" maxlength="7" spellcheck="false" :aria-invalid="raw[key]!==undefined&&!isHex(raw[key])" @input="input(key,($event.target as HTMLInputElement).value)" /></div><small v-if="raw[key]!==undefined&&!isHex(raw[key])" class="error" role="alert">请输入 # 加六位十六进制颜色，修正后才能保存。</small></div></div><div v-if="warnings.length" class="contrast-warnings" role="status"><strong>文字对比度提醒（建议至少 4.5:1）</strong><p v-for="w in warnings" :key="w.label">{{w.label}}：{{w.ratio.toFixed(2)}}:1</p><small>Glass 半透明表面的实际对比度也受底色影响，建议在真实预览中确认。</small></div><button type="button" class="quiet" @click="clearTheme">{{appearance.palette?'恢复当前组合默认颜色（待保存）':'清除当前主题全部颜色覆盖（待保存）'}}</button></section></template>
<style scoped>
.color-editor{margin:28px 0;padding-top:20px;border-top:1px solid var(--ui-line)}.color-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:20px 0}.color-row{border:1px solid var(--ui-line);border-radius:var(--ui-radius);padding:16px;min-width:0;background:var(--ui-card);color:var(--ui-ink)}.color-inputs{display:flex;gap:12px;align-items:center}.color-inputs input[type=color]{width:52px;min-width:52px;height:44px;padding:4px;margin:0}.color-inputs input:not([type=color]){min-width:0;margin:0;font-family:monospace}.color-row .checks{font-size:14px;margin:10px 0}.color-row small{display:block;margin-top:8px}.contrast-warnings{padding:16px;border:1px solid var(--ui-danger);border-radius:var(--ui-radius);background:var(--ui-card);color:var(--ui-danger);margin:20px 0}.contrast-warnings p{margin:6px 0;font-size:14px}@media(max-width:700px){.color-grid{grid-template-columns:1fr}}
</style>
